const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=value=>String(value??'').trim().toLocaleLowerCase('pt-BR');
const circleLabel=level=>level===0?'Truque':Number.isInteger(level)?`${level}º círculo`:'Círculo não informado';
const safeLink=url=>{try{const parsed=new URL(url);return ['https:','http:'].includes(parsed.protocol)?parsed.href:''}catch{return ''}};

export function spellCatalog(rules,tableSpells,classes,tableId){
 const classByName=new Map(classes.map(c=>[norm(c.name),c.id]));
 const classBySlug=new Map(classes.filter(c=>c.slug).map(c=>[c.slug,c.id]));
 const official=(rules||[]).filter(r=>r.kind==='spell').map(r=>{
  const m=r.metadata||{}, raw=m.spell_level, level=raw===null||raw===undefined||raw===''?null:Number(raw);
  const classIds=[...(Array.isArray(m.classes)?m.classes:[]).map(name=>classByName.get(norm(name))),m.class_id,classBySlug.get(m.class_slug),classByName.get(norm(m.class_name))].filter(Boolean);
  return {key:`official:${r.id}`,name:String(r.name||''),level:Number.isInteger(level)&&level>=0&&level<=9?level:null,classes:[...new Set(classIds)],description:String(r.content||r.summary||''),summary:String(r.summary||''),sourceName:r.source_name,sourceUrl:safeLink(r.source_url),sourcePage:r.source_page,license:r.license,metadata:m,origin:'official'};
 });
 const custom=(tableSpells||[]).filter(s=>s.table_id===tableId&&s.status==='approved').map(s=>({key:`table:${s.id}`,name:String(s.name||''),level:Number(s.spell_level),classes:Array.isArray(s.classes)?s.classes:[],description:String(s.description||''),summary:String(s.description||''),metadata:{casting_time:s.casting_time,range:s.spell_range,components:s.components,duration:s.duration,school:s.school},origin:'table'}));
 return [...official,...custom].sort((a,b)=>(a.level??99)-(b.level??99)||a.name.localeCompare(b.name,'pt-BR'));
}
export function filterSpells(spells,{query='',classId='',circle=''}={}){
 const q=norm(query);
 return spells.filter(s=>(!classId||s.classes.includes(classId))&&(circle===''||s.level===Number(circle))&&(!q||norm(`${s.name} ${s.summary} ${s.description}`).includes(q)));
}
function spellCard(s,classNames){
 const names=s.classes.map(id=>classNames.get(id)).filter(Boolean),meta=s.metadata||{};
 const fields=[['Escola',meta.school],['Conjuração',meta.casting_time],['Alcance',meta.range],['Componentes',meta.components],['Duração',meta.duration],['Especial',meta.special]].filter(([,v])=>typeof v==='string'&&v.trim()&&v!=='—');
 const source=s.sourceUrl?`<a href="${esc(s.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(s.sourceName||'Ver fonte')} ↗</a>`:esc(s.sourceName||'');
 return `<article class="panel spell-catalog-card"><div class="spell-catalog-meta"><span>${esc(circleLabel(s.level))}</span><span>${s.origin==='table'?'Da mesa':'Catálogo'}</span></div><h3>${esc(s.name)}</h3>${s.summary?`<p>${esc(s.summary)}</p>`:''}${names.length?`<p class="note">${esc(names.join(' · '))}</p>`:''}<details><summary>Ver detalhes</summary>${fields.length?`<dl class="spell-info">${fields.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`:''}<p class="spell-description">${esc(s.description)}</p>${s.origin==='official'?`<p class="note">${source}${s.sourcePage?' · '+esc(s.sourcePage):''}${s.license?'<br>'+esc(s.license):''}</p>`:''}</details></article>`;
}
export function proposalDetails(spell,classNames){
 const names=(Array.isArray(spell.classes)?spell.classes:[]).map(id=>classNames.get(id)).filter(Boolean);
 const fields=[['Classes',names.join(', ')||'Não informadas'],['Escola',spell.school],['Conjuração',spell.casting_time],['Alcance',spell.spell_range],['Componentes',spell.components],['Duração',spell.duration]].filter(([,value])=>typeof value==='string'&&value.trim());
 return `<dl class="spell-info">${fields.map(([key,value])=>`<div><dt>${esc(key)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl><p class="spell-description">${esc(spell.description)}</p>`;
}
function creationForm(classes,isGm){
 return `<p class="note">${isGm?'A magia ficará disponível para esta mesa.':'Sua proposta ficará disponível para o mestre revisar.'}</p><label>Nome<input name="name" required maxlength="100"></label><div class="grid two"><label>Círculo<select name="spell_level">${Array.from({length:10},(_,i)=>`<option value="${i}">${esc(circleLabel(i))}</option>`).join('')}</select></label><label>Escola<input name="school" maxlength="100"></label></div><div class="spell-class-field"><span id="spell-class-label">Classes</span><details class="spell-class-picker"><summary aria-labelledby="spell-class-label spell-class-summary"><span id="spell-class-summary">Selecionar classes</span></summary><div class="spell-class-options">${classes.map(c=>`<label><input type="checkbox" name="classes" value="${esc(c.id)}"><span>${esc(c.name)}</span><span class="spell-class-check" aria-hidden="true">✓</span></label>`).join('')}</div></details><small>Selecione todas as classes que podem usar esta magia.</small></div><div class="grid two"><label>Tempo de conjuração<input name="casting_time" maxlength="200"></label><label>Alcance<input name="spell_range" maxlength="200"></label><label>Componentes<input name="components" maxlength="500"></label><label>Duração<input name="duration" maxlength="200"></label></div><label>Descrição<textarea name="description" required maxlength="10000" rows="5"></textarea></label>`;
}
export function mountSpellsView({container,rules,tableSpells,classes,tableId,isGm,modal,onCreate,onReview,onRefresh,onError}){
 const catalog=spellCatalog(rules,tableSpells,classes,tableId),classNames=new Map(classes.map(c=>[c.id,c.name]));
 const proposals=(tableSpells||[]).filter(s=>s.table_id===tableId&&s.status!=='approved').sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')));
 container.innerHTML=`<div class="heading"><div><h1>Magias</h1><p>Consulte magias do catálogo e criações da sua mesa.</p></div><div class="actions"><button id="spell-refresh">Atualizar lista</button><button id="spell-create" class="primary">＋ Criar magia</button></div></div>${proposals.length?`<section class="panel spell-proposals"><h2>${isGm?'Propostas da mesa':'Minhas propostas'}</h2>${proposals.map(s=>`<div class="row"><div><b>${esc(s.name)}</b><p>${esc(circleLabel(Number(s.spell_level)))} · ${s.status==='pending'?'Aguardando mestre':'Rejeitada'}</p><details><summary>Ver detalhes</summary>${proposalDetails(s,classNames)}</details></div>${isGm&&s.status==='pending'?`<div class="actions"><button data-spell-review="${esc(s.id)}" data-approve="false">Rejeitar</button><button class="primary" data-spell-review="${esc(s.id)}" data-approve="true">Aprovar</button></div>`:''}</div>`).join('')}</section>`:''}<div class="toolbar spell-catalog-tools"><input id="spell-search" type="search" placeholder="Buscar magia" aria-label="Buscar magia"><select id="spell-class" aria-label="Filtrar por classe"><option value="">Todas as classes</option>${classes.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select><select id="spell-circle" aria-label="Filtrar por círculo"><option value="">Todos os círculos</option>${Array.from({length:10},(_,i)=>`<option value="${i}">${esc(circleLabel(i))}</option>`).join('')}</select></div><p class="note" id="spell-count" aria-live="polite"></p><div id="spell-results"></div><p class="note">O catálogo usa as fontes registradas no Glossário e pode não conter todas as magias. As criações aprovadas ficam disponíveis apenas nesta mesa.</p>`;
 const query=sel=>container.querySelector(sel),results=query('#spell-results');
 const draw=()=>{const list=filterSpells(catalog,{query:query('#spell-search').value,classId:query('#spell-class').value,circle:query('#spell-circle').value});query('#spell-count').textContent=`${list.length} ${list.length===1?'magia encontrada':'magias encontradas'}`;results.innerHTML=list.length?`<div class="spell-catalog-grid">${list.map(s=>spellCard(s,classNames)).join('')}</div>`:'<div class="empty"><h2>Nenhuma magia encontrada</h2><p>Tente outro nome, classe ou círculo.</p></div>';};
 let searchTimer;query('#spell-search').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(draw,100)});query('#spell-class').addEventListener('change',draw);query('#spell-circle').addEventListener('change',draw);draw();
 query('#spell-refresh').addEventListener('click',async e=>{e.currentTarget.disabled=true;try{await onRefresh()}catch(error){onError(error);e.currentTarget.disabled=false}});
 query('#spell-create').addEventListener('click',()=>{modal('Criar magia',creationForm(classes,isGm),async form=>{const selected=form.getAll('classes');if(!selected.length)throw Error('Selecione ao menos uma classe.');await onCreate({name:String(form.get('name')||'').trim(),spell_level:Number(form.get('spell_level')),classes:selected,description:String(form.get('description')||'').trim(),casting_time:String(form.get('casting_time')||'').trim(),spell_range:String(form.get('spell_range')||'').trim(),components:String(form.get('components')||'').trim(),duration:String(form.get('duration')||'').trim(),school:String(form.get('school')||'').trim()});});const dialog=document.querySelector('#dialog');dialog?.querySelectorAll('[name=classes]').forEach(el=>el.addEventListener('change',()=>{const names=[...dialog.querySelectorAll('[name=classes]:checked')].map(x=>x.nextElementSibling.textContent);dialog.querySelector('#spell-class-summary').textContent=names.length?(names.length<=3?names.join(', '):`${names.slice(0,2).join(', ')} e mais ${names.length-2}`):'Selecionar classes';}));});
 container.querySelectorAll('[data-spell-review]').forEach(button=>button.addEventListener('click',async()=>{if(button.disabled)return;button.disabled=true;try{await onReview(button.dataset.spellReview,button.dataset.approve==='true');}catch(error){onError(error);button.disabled=false;}}));
}
